const items = $input.all();
const rows = items.map(i => i.json);
const dateStr = new Date().toISOString().split('T')[0];

let md = `# Weekly Funding Digest - ${dateStr}\n\n`;
md += `**${rows.length} open opportunities discovered this week**\n\n`;

if (rows.length === 0) {
  md += '_No new funding opportunities discovered this week._\n';
} else {
  md += '| Title | Funder | Region | Deadline | URL |\n';
  md += '|-------|--------|--------|----------|-----|\n';
  for (const row of rows) {
    const title = (row.title || 'N/A').replace(/\|/g, '\\|');
    const funder = (row.funder || 'N/A').replace(/\|/g, '\\|');
    const region = (row.region || 'N/A').replace(/\|/g, '\\|');
    const deadline = row.deadline ? new Date(row.deadline).toISOString().split('T')[0] : 'TBD';
    const url = row.url || '';
    md += `| ${title} | ${funder} | ${region} | ${deadline} | ${url} |\n`;
  }
}

return [{ json: { markdown: md, dateStr, count: rows.length } }];
